#!/usr/bin/env node
'use strict';
// Stage C: independent expected itineraries, not expectations generated by the engine.
const {test}=require('node:test');
const assert=require('node:assert/strict');
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),crypto=require('node:crypto');
const root=path.resolve(__dirname,'..');
const html=fs.readFileSync(path.join(root,'konverzace/city-quest-f2/index.html'),'utf8');
const script=html.match(/<script>([\s\S]*?)<\/script>/)[1];
// Compile ALL inline JavaScript, not only the pure engine section.
new vm.Script(script,{filename:'city-quest-inline.js'});
const start=script.indexOf('/* Riverton Metro — F2.1B experimental network and route engine.');
const end=script.indexOf('/* City Quest F2.1D — manually authored metro languages and CEFR pedagogy.',start);
assert.ok(start>=0&&end>start,'Isolated engine boundary');
const context=vm.createContext({});
vm.runInContext(script.slice(start,end),context,{timeout:5000});
const M=context.RivertonMetro,MG=context.RivertonMetroGame;
const local=x=>JSON.parse(JSON.stringify(x));
const levels=['B2','C1','C2'];
const fixtures={
 5:[
  [{line:'M1',direction:'east_gardens',platform:'2',stops:['central_station','old_town','museum_quarter']}],
  [{line:'M2',direction:'north_park',platform:'3',stops:['central_station','university']},{line:'M3',direction:'harbour',platform:'3',stops:['university','science_centre','museum_quarter']}]
 ],
 6:[
  [{line:'M2',direction:'north_park',platform:'1',stops:['market_square','central_station','university']},{line:'M3',direction:'harbour',platform:'3',stops:['university','science_centre','museum_quarter','stadium']}],
  [{line:'M2',direction:'north_park',platform:'1',stops:['market_square','central_station']},{line:'M1',direction:'east_gardens',platform:'2',stops:['central_station','old_town','museum_quarter']},{line:'M3',direction:'harbour',platform:'3',stops:['museum_quarter','stadium']}]
 ]
};
const expectedAnswer={B2:'exact',C1:'adapt',C2:'verified'};
function act(state,type,value,extra){
 const r=MG.act(state,{type,value,...extra});
 assert.equal(r.accepted,true,type+' rejected: '+r.message+' ('+state.phase+'/'+state.metroStation+')');
 return r.state;
}
function rejects(state,type,value,extra){
 const r=MG.act(state,{type,value,...extra});
 assert.equal(r.accepted,false,type+' incorrectly accepted');
 assert.equal(r.state.phase,state.phase);
 assert.equal(r.state.metroStation,state.metroStation);
 assert.equal(r.state.completed,state.completed);
 return r.state;
}
function take(state,legs){
 for(let i=0;i<legs.length;i++){
  const leg=legs[i];
  if(i===0)state=act(state,'SELECT_LINE',leg.line);
  else{
   state=act(state,'TRANSFER_HERE');
   if(state.phase==='checkpoint')state=act(state,'SELF_CHECK');
   state=act(state,'CHANGE_LINE',leg.line);
  }
  state=act(state,'SELECT_DIRECTION',leg.direction);
  state=act(state,'SELECT_PLATFORM',leg.platform);
  state=act(state,'BOARD');
  for(const stop of leg.stops.slice(1)){
   state=act(state,'NEXT_STOP');
   assert.equal(state.metroStation,stop,'Actual physical stop');
  }
 }
 state=act(state,'EXIT_HERE');
 state=act(state,'EXIT');
 return state;
}
function finish(state){
 if(state.level!=='B1'){
  state=rejects(state,'SELF_CHECK');
  state=rejects(state,'REVIEW_ROUTE','not-valid');
  assert.equal(state.reviewAttempts,1);
  state=act(state,'REVIEW_ROUTE',expectedAnswer[state.level]);
  assert.equal(state.reviewPassed,true);
 }
 state=act(state,'SELF_CHECK');
 assert.equal(state.completed,true);
 return state;
}
test('Graph enumerates exactly the two independently specified legal routes for missions 05/06 at B2-C2',()=>{
 for(const n of [5,6]){
  assert.equal(MG.routeVariants(n,'B1').length,1);
  for(const level of levels){
   const expected=fixtures[n].map(legs=>legs.map(({line,stops})=>({line,stops})));
   assert.deepEqual(local(MG.routeVariants(n,level)),expected,n+'/'+level);
   assert.deepEqual(local(MG.routeVariants(n,level).map(MG.routeCost)),n===5?[6,13]:[19,20]);
  }
 }
 assert.equal(M.platformSigns('museum_quarter').find(s=>s.line==='M3'&&s.directionTerminus==='harbour').platform,'3');
});
test('Every canonical and alternative route completes independently for every advanced CEFR level',()=>{
 for(const n of [5,6])for(const level of levels)for(let variant=0;variant<2;variant++){
  let state=take(MG.start(n,level),fixtures[n][variant]);
  assert.equal(state.phase,'speech');
  assert.equal(state.routeVariant,variant);
  const evidence=MG.journeySummary(state);
  assert.equal(evidence.stops,n===5?(variant?3:2):(variant?4:5));
  assert.equal(evidence.transfers,n===5?variant:(variant?2:1));
  assert.equal(evidence.simulatedMinutes,n===5?(variant?13:6):(variant?20:19));
  assert.deepEqual(local(evidence.boards.map(b=>[b.station,b.line,b.direction,b.platform])),
    fixtures[n][variant].map(l=>[l.stops[0],l.line,l.direction,l.platform]));
  state=finish(state);
 }
});
test('B1 fixed instruction and advanced early-transfer stay remain safe',()=>{
 let state=rejects(MG.start(5,'B1'),'SELECT_LINE','M2');
 state=take(state,fixtures[5][0]);finish(state);
 state=MG.start(6,'B2');
 for(const [type,value] of [['SELECT_LINE','M2'],['SELECT_DIRECTION','north_park'],['SELECT_PLATFORM','1'],['BOARD'],['NEXT_STOP']])
  state=act(state,type,value);
 assert.equal(state.metroStation,'central_station');
 state=act(state,'TRANSFER_HERE');
 assert.equal(state.routeVariant,1);
 state=rejects(state,'CHANGE_LINE','M3');
 state=act(state,'STAY_ON_LINE');
 assert.equal(state.routeVariant,0);
 assert.equal(state.phase,'ride');
 state=act(state,'NEXT_STOP');
 assert.equal(state.metroStation,'university');
});
test('Physical errors and overrun/reversal never create false completion or invented evidence',()=>{
 let s=MG.start(5,'C2');
 s=rejects(s,'EXIT_HERE');
 s=act(s,'SELECT_LINE','M1');
 s=rejects(s,'SELECT_DIRECTION','west_end');
 s=act(s,'SELECT_DIRECTION','east_gardens');
 s=rejects(s,'SELECT_PLATFORM','1');
 s=act(s,'SELECT_PLATFORM','2');s=act(s,'BOARD');
 s=act(s,'NEXT_STOP');
 s=rejects(s,'EXIT_HERE');s=rejects(s,'TRANSFER_HERE');
 s=act(s,'NEXT_STOP');s=act(s,'NEXT_STOP');
 assert.equal(s.metroStation,'riverside');
 s=rejects(s,'EXIT_HERE');s=act(s,'TURN_BACK');s=act(s,'NEXT_STOP');
 assert.equal(s.metroStation,'museum_quarter');
 s=act(s,'EXIT_HERE');s=act(s,'EXIT');
 const evidence=MG.journeySummary(s);
 assert.equal(evidence.stops,4);
 assert.equal(evidence.transfers,0);
 assert.equal(evidence.reversals.length,1);
 assert.equal(evidence.simulatedMinutes,16);
 finish(s);
});
test('Disruption and mandatory ticket/meeting constraints remain enforced at every CEFR',()=>{
 const alternate7=[{line:'M2',direction:'north_park',platform:'3',stops:['central_station','university']},
  {line:'M3',direction:'harbour',platform:'3',stops:['university','science_centre','museum_quarter']}];
 const mixed8=[{line:'M2',direction:'north_park',platform:'1',stops:['market_square','central_station','university']},
  {line:'M3',direction:'harbour',platform:'3',stops:['university','science_centre','museum_quarter']}];
 for(const level of ['B1',...levels]){
  assert.equal(MG.routeVariants(7,level).length,1);
  assert.equal(MG.routeVariants(8,level).length,1);
  let s=MG.start(7,level);
  s=rejects(s,'SELECT_LINE','M2');
  s=act(s,'READ_NOTICE');s=rejects(s,'SELECT_LINE','M1');
  s=take(s,alternate7);finish(s);
  s=MG.start(8,level);s=rejects(s,'ENTER');
  for(const node of [{c:1,r:3},{c:2,r:3},{c:2,r:2}])s=act(s,'WALK',undefined,{node});
  assert.equal(s.phase,'checkpoint');
  s=rejects(s,'ENTER');
  s=act(s,'SELF_CHECK');assert.equal(s.ticketsCollected,true);s=act(s,'ENTER');
  s=take(s,mixed8);
  assert.equal(s.phase,'walk-to-museum');
  assert.equal(s.meetingConfirmed,true);
  s=act(s,'WALK',undefined,{node:{c:3,r:1}});
  assert.equal(s.phase,'speech');assert.equal(s.speakingDone,2);
  const summary=MG.journeySummary(s);
  assert.equal(summary.entryWalk.length,4);
  assert.equal(summary.exitWalk.length,2);
  assert.ok(summary.ticketsCollected&&summary.meetingConfirmed);
  s=finish(s);assert.equal(s.speakingDone,3);
 }
});
test('Stage C preserves offline integrity, original geometry and explicit speaking disclaimer',()=>{
 const manifest=JSON.parse(fs.readFileSync(path.join(root,'version.json'),'utf8'));
 assert.equal(crypto.createHash('sha256').update(html).digest('hex'),manifest.contentHashes['cl-city-quest-f2']);
 assert.match(html,/connect-src 'none'/);
 assert.match(html,/portalEnd=\{c:3,r:2\},museum=\{c:3,r:1\}/);
 assert.doesNotMatch(html,/SpeechRecognition|webkitSpeechRecognition|navigator\.mediaDevices\.getUserMedia/);
 assert.match(html,/completedLegs:state\.completedLegs\.concat/);
 assert.match(html,/if\(state\.done\.size===8\)renderCompletionSummary\(\)/);
 assert.match(html,/function cityDecisionPlan\(level,n\)/);
 assert.doesNotMatch(html,/realized\+" "\+profile\(\)\.model/);
});
